    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "To be eligible for inclusion in the present review, studies needed to meet the following criteria: (i) were children or adolescents aged 5-19 years, all countries and ethnic backgrounds; (ii) had a MetS outcome; (iii) had an adherence to the MedDiet assessed by a validated questionnaire; and (iv) had a longitudinal and cross-­ sectional study design.",
      "reason": "Eligibility specifies key study characteristics (population age 5–19, outcome MetS, exposure assessed with a validated questionnaire, and eligible study designs including longitudinal and cross-sectional). However, follow-up requirements are not specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "Furthermore, the need to convert data for the purpose of quantitative analysis presents an additional limitation to our study; additionally, we restricted our inclusion criteria to studies published in English.",
      "reason": "The review specifies a language restriction (published in English), but dissemination year and publication/report status are not reported in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not distinguish exclusions based on (a) outcomes not measured versus (b) outcome results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not specify the groups used in each synthesis and how they were linked to the comparisons in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "However, to narrow the scope of the meta-­ analysis, only studies that associated the MedDiet with the outcome of MetS were included.",
      "reason": "A rationale is provided for a notable eligibility restriction (including only studies that associated MedDiet with MetS to narrow the scope). No further rationale for other restrictions is provided in the retrieved evidence."
    }
  ],
  "confidence": 62
}

